-- 019 — The video production queue.
--
-- One row per short personal-finance video (5-15 minutes, one core idea),
-- seeded with the 100-topic bite-size curriculum built 2026-10-06 from the
-- class series and the Personal Finance Brain. Scripts are written in a Claude
-- Code session from the brain's trusted sources (on the subscription, like
-- extraction and weekly posts) and filed with `cli.php video-import`, which
-- `worker/video_push.py` drives. Nothing here calls a model.
--
-- `status` is the production pipeline Jassen moves a video through by hand:
-- topic -> scripted -> approved -> recorded -> edited -> published, or skipped.
-- `sources` keeps the brain citations the script rests on, so a claim can be
-- traced before recording; `notes` holds what must be updated or decided first.

CREATE TABLE IF NOT EXISTS video_scripts (
  id           INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  number       SMALLINT UNSIGNED NOT NULL,
  part_no      TINYINT UNSIGNED NOT NULL,
  part_title   VARCHAR(80) NOT NULL,
  topic        VARCHAR(255) NOT NULL,
  slug         VARCHAR(100) NOT NULL,
  status       ENUM('topic','scripted','approved','recorded','edited','published','skipped')
               NOT NULL DEFAULT 'topic',
  title        VARCHAR(255) NULL,
  script       MEDIUMTEXT NULL,
  on_screen    TEXT NULL,
  sources      TEXT NULL,
  notes        TEXT NULL,
  words        SMALLINT UNSIGNED NULL,
  runtime_min  TINYINT UNSIGNED NULL,
  model        VARCHAR(40) NULL,
  scripted_at  DATETIME NULL,
  video_url    VARCHAR(500) NULL,
  published_at DATE NULL,
  my_notes     TEXT NULL,
  created_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_video_number (number),
  KEY ix_video_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

